ALTER TABLE stale_chapters ADD COLUMN paths_json JSON NULL AFTER reasons_json, ADD COLUMN status VARCHAR(24) NOT NULL DEFAULT 'STALE' AFTER paths_json, ADD COLUMN resolved_at DATETIME(6) NULL AFTER created_at, ADD COLUMN resolved_by VARCHAR(64) NULL AFTER resolved_at, ADD COLUMN resolution_note VARCHAR(1000) NULL AFTER resolved_by;
CREATE TABLE IF NOT EXISTS stale_chapter_history (id VARCHAR(40) PRIMARY KEY, project_id VARCHAR(32) NOT NULL, branch_id VARCHAR(64) NOT NULL, chapter_version_id VARCHAR(32) NOT NULL, from_status VARCHAR(24) NOT NULL, to_status VARCHAR(24) NOT NULL, actor_id VARCHAR(64) NOT NULL, note VARCHAR(1000) NOT NULL DEFAULT '', created_at DATETIME(6) NOT NULL, INDEX idx_stale_history_chapter(project_id,branch_id,chapter_version_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
